<section class="workflow-page" x-data="resourcePage({ endpoint: 'notifications', columns: [], perPage: 10 })" x-init="load()">
    <div class="workflow-filters"><label>Search notifications<input type="search" x-model="search" @input.debounce.350ms="load(1)"></label><label><input type="checkbox" x-model="unreadOnly" @change="load(1)">Unread only</label><label>Type<select x-model="typeFilter" @change="load(1)"><option value="">All types</option><option value="evidence_requested">Evidence requests</option><option value="evidence_reviewed">Evidence reviewed</option><option value="status_changed">CAR updates</option><option value="corrective_action_created">Corrective action created</option><option value="compliant_confirmed">Compliance confirmed</option><option value="admin_broadcast">Announcements</option></select></label></div>
    <p x-show="error" x-text="error" role="alert"></p><p x-show="successPopupVisible" x-text="successPopupMessage" role="status"></p><p x-show="loading">Loading notifications…</p><div x-cloak x-show="!loading && !rows.length" class="auditor-assignment-empty"><i data-lucide="bell"></i><h2>No notifications found</h2><p>Updates remain available here when you return.</p></div>
    <template x-for="notification in rows" :key="notification._id"><article class="workflow-card notification-feed-row" :class="notification.isRead ? '' : 'notification-unread'"><div class="notification-feed-heading"><h2 x-text="notification.title"></h2><span x-text="notification.isRead ? 'Read' : 'Unread'"></span><time :datetime="notification.createdAt" x-text="new Date(notification.createdAt).toLocaleString()"></time></div><p x-text="notification.message"></p><p class="workflow-muted" x-text="notification.type.replaceAll('_',' ')"></p><div class="workflow-actions"><a x-show="notification.destination && notification.destination.startsWith('/') && !notification.destination.startsWith('//')" :href="notification.destination">View related record</a><button x-show="!notification.isRead" @click="markRead(notification)" class="workflow-secondary">Mark read</button></div></article></template>
    <nav class="workflow-actions" aria-label="Notification pages"><button @click="load(page-1)" :disabled="page <= 1 || loading" class="workflow-secondary">Previous</button><span x-text="`Page ${page} of ${meta.lastPage || 1}`"></span><button @click="load(page+1)" :disabled="page >= meta.lastPage || loading" class="workflow-secondary">Next</button></nav>
</section>
@endsection
